# coding: utf-8
from lesson_authoring import entry as E
B=[['拉丁 sal','盐']]
W=[
E('salad','/ˈsæləd/','沙拉；拌制的冷菜','把切好的蔬菜或其他食材拌在一起，再加调味汁。','拉丁盐相关动词的“加盐的”形式，经意大利语、法语 salade 等进入英语。',B+[['俗拉丁 *salata／意大利 salata、salada','加盐调味的蔬菜'],['古法语 salade → 英语 salad','拌蔬菜 → 各类沙拉']],'早期名字与给蔬菜加盐调味有关；现代可以是水果、土豆、鸡肉等组成的沙拉，不要求每一道都明显咸。词源告诉你最初怎样命名，不能拿来限制现代菜谱。','a green salad；fruit salad；potato salad；salad dressing。','salad 不是 lettuce 生菜的同义词。生菜可以是原料，但没有生菜的沙拉也很多。',('She made a salad with tomatoes, cucumbers, and beans.','她用番茄、黄瓜和豆子做了一份沙拉。'),('We served fruit salad after the meal.','饭后我们端上了水果沙拉。'),sources=['https://www.etymonline.com/word/salad','https://en.wiktionary.org/wiki/salad']),
E('sauce','英 /sɔːs/；美 /sɔs/','酱汁；调味汁','给主食或菜肴加上一层味道的液体或半流体。','拉丁 salsus 加盐的，其名词化形式 salsa 经古法语 sauce、sausse 借入。',B+[['拉丁 salsus → salsa → 古法语 sauce','加盐的 → 调味物、酱汁'],['英语 sauce','给食物添味的汁；后来也有添辣、放肆的比喻']],'tomato sauce 是番茄酱汁，chocolate sauce 是巧克力淋酱。虽然远源是盐，现代 sauce 可以甜；它的范围远大于一瓶 ketchup。','pasta sauce；tomato sauce；soy sauce；serve with a sauce。','sauce 是酱汁的广义词；gravy 常指与肉汁相关的浇汁。英式英语里 sauce 与 source 常同音，含义不同。',('Add the sauce just before serving.','上桌前再加入酱汁。'),('The dessert came with a warm chocolate sauce.','甜点配有温热的巧克力淋酱。'),sources=['https://www.etymonline.com/word/sauce','https://en.wiktionary.org/wiki/sauce']),
E('salsa','英 /ˈsælsə/；美 /ˈsɑlsə/','莎莎酱；萨尔萨音乐或舞蹈','食物里是带风味的酱，音乐里借这个名字表现热烈、有味道的风格。','西班牙 salsa 酱，源自拉丁 salsa；食品义与音乐义在不同时期分别借入英语。',B+[['拉丁 salsa → 西班牙 salsa','加盐调味物 → 酱'],['英语 salsa 的两次借用','食物酱料；后来作为音乐及舞蹈名称']],'英语食品语境常指番茄、辣椒等制成的莎莎酱，但配方不只有一种。take salsa classes 则是学萨尔萨舞；不能因为相同拼写就把这句话想成做菜课。','tomato salsa；chips and salsa；salsa music；a salsa class。','sauce 与 salsa 远源相同，但英语里 sauce 是广义酱汁，salsa 通常指特定饮食或音乐舞蹈语境。',('We dipped the tortilla chips into the salsa.','我们用玉米片蘸莎莎酱吃。'),('They take salsa classes every Friday evening.','他们每周五晚上上萨尔萨舞课。'),sources=['https://www.etymonline.com/word/salsa','https://en.wiktionary.org/wiki/salsa']),
E('salami','/səˈlɑːmi/','萨拉米香肠；意式腌制香肠','切成薄片后，能看见肉与脂肪相间的腌制香肠。','意大利 salami 是 salame 的复数，源于 sale 盐，最终接拉丁 sal。',B+[['拉丁 sal → 意大利 sale → salame／salami','盐 → 用盐腌制的肉食'],['英语 salami','借来的香肠名称，可作物质名词']],'英语里 some salami 可以说一些萨拉米切片；a salami 可以指一整条。虽然意大利来源是复数，进入英语后形成了自己的用法，不必照搬意大利语单复数规则。','sliced salami；a salami sandwich；a piece of salami。','salami 是 sausage 香肠中的一类，不能把所有香肠都叫 salami；salmon 则是三文鱼，来源不同。',('He added a few slices of salami to the sandwich.','他往三明治里加了几片萨拉米香肠。'),('The deli sells several varieties of salami.','熟食店出售几种不同的萨拉米香肠。')),
E('sausage','英 /ˈsɒsɪdʒ/；美 /ˈsɔsɪdʒ/','香肠；香肠肉','把调好味的肉馅等装入肠衣，做成条状食物。','后期拉丁 salsicia 一族，接 salsus 加盐的，经法语 sausiche 等借入。',B+[['拉丁 salsus → 后期拉丁香肠名称','加盐调味的 → 腌制肉食'],['盎格鲁法语 sausiche → 英语 sausage','香肠']],'a sausage 是一根香肠；sausage meat 是做香肠用的馅。今天也有 vegetarian sausage，名称可以延伸到模仿这类形态和吃法的食品。','grilled sausages；sausage meat；a sausage roll；vegetarian sausages。','sausage 是类别总称；salami 是具体类型。hot dog 可以指热狗肠，也常指夹着肠的面包食品。',('We grilled sausages for lunch.','我们午饭烤了香肠。'),('The recipe uses sausage meat and chopped onions.','这道食谱使用香肠肉馅和切碎的洋葱。')),
E('saucer','英 /ˈsɔːsə/；美 /ˈsɔsər/','茶碟；浅碟','杯子底下托着的一只小浅碟，接住滴落的液体。','古法语 saussier 与盎格鲁拉丁 saucerium 等指盛酱的小碟，后来转为杯碟。',B+[['拉丁 salsus → 盛酱器皿名称 → 古法语 saussier','加盐调味物 → 酱碟'],['英语 saucer','小浅碟 → 托杯子的茶碟']],'原本盛 sauce 的小碟，后来成了杯子下面的碟子；这是用途改变带来的词义变化。flying saucer 借它扁圆的形状表示飞碟，不是在说真的餐具会飞。','a cup and saucer；a china saucer；a flying saucer。','saucer 不是“做酱的人”，-er 在这个借词里不能机械当职业后缀。plate 通常是更宽泛的盘子。',('She set the cup carefully on its saucer.','她小心地把杯子放回茶碟上。'),('The child drew a flying saucer above the house.','孩子在房子上方画了一只飞碟。'),sources=['https://www.etymonline.com/word/saucer','https://en.wiktionary.org/wiki/saucer']),
E('saucepan','英 /ˈsɔːspən/；美 /ˈsɔsˌpæn/','长柄深锅；小炖锅','有一定深度和一根长柄，可以在炉上煮水、热汤或做酱汁。','英语 sauce 酱汁 + pan 锅，按用途命名的复合词。',[['拉丁盐相关词 → 英语 sauce；英语 pan','酱汁；锅'],['sauce + pan → saucepan','做酱用的锅 → 常见长柄深锅']],'名字里有 sauce，但 saucepan 当然不只用来做酱；煮奶、热汤、煮小份食物都常用。掌握器皿形状和用法，比硬记“酱锅”更实用。','a small saucepan；a heavy saucepan；heat something in a saucepan。','frying pan 通常浅而宽，适合煎；saucepan 通常更深，适合处理液体和炖煮。具体锅具也会有不同设计。',('Warm the milk in a small saucepan.','用一口小长柄锅温热牛奶。'),('She lifted the saucepan off the heat.','她把长柄锅从炉火上端开。'))]
